export const duration = ms => typeof ms !== 'number' || !Number.isFinite(ms) ? '—' : ms < 60000 ? `${fmt(ms / 1000)} 秒` : `${Math.floor(ms / 60000)} 分 ${fmt(ms % 60000 / 1000)} 秒`;
